                </p>
              </div>
              
            </div>
          </div>
        `,
      }
    ]);

    if (error) {
      console.error("Resend Error:", error);
      return { success: false, message: error.message };
    }

    return { success: true };
  } catch (err: any) {
    console.error("Server Action Error:", err);
    return { success: false, message: err.message || "Unknown error" };
  }
}

