"use client";

import Image from "next/image";
import { portfolioData, doodleItem } from "@/data/portfolio";
import {
  motion,
  useScroll,
  useTransform,
  useSpring,
  useInView,
  animate,
  AnimationPlaybackControls,
} from "framer-motion";
import { useRef, useState, useEffect, useMemo } from "react";

const targetIds = ["port-1", "port-2", "port-3", "port-4"];

const displayPortfolios = [
  ...targetIds
    .map((id) => portfolioData.find((item) => item.id === id))
    .filter(Boolean)
    .map((item) => ({ ...item, type: "portfolio" })),
];

export default function Portfolio() {
  const containerRef = useRef(null);

  // Baca progres scroll dari container raksasa
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start start", "end end"],
  });

  // THE BUTTER HACK 🧈 (TWEAKED FOR CINEMATIC SLOW-MO)
  const smoothProgress = useSpring(scrollYProgress, {
    mass: 0.8, // Kartu dibikin lebih "berat" biar geraknya ngalir
    stiffness: 50, // Tarikan per-scroll dilembutin (gak terlalu responsif/agresif)
    damping: 25, // Rem-nya dibikin lebih pakem biar berhentinya super mulus
    restDelta: 0.001,
  });

  return (
    // THE TRACK LENGTH: Diperpanjang jadi 1600vh!
    // Ini bikin user harus nge-scroll lebih panjang untuk nyelesaiin 100% animasi.
    // Hasilnya? Tiap kartu bakal jalan jauh lebih lambat dan elegan melintasi layar.
    <section
      ref={containerRef}
      className="relative w-full z-10 overflow-x-clip overflow-y-visible h-[1600vh] bg-surface-light"
    >
      {/* THE STICKY STAGE */}
      <div className="sticky top-0 flex h-screen w-full items-center justify-center bg-surface-light">
        {/* BACKGROUND DOODLES (Z-0) */}
        <ParallaxDoodles smoothProgress={smoothProgress} />

        {/* FASE 1: THE INK-SPILL INTRO (Z-10) */}
        <IntroHeroSection smoothProgress={smoothProgress} />

        {/* FASE 2: THE DIAGONAL DECK (Z-20 sampai Z-30) */}
        {displayPortfolios.map((port, idx) => (
          <DiagonalDeckCard
            key={port.id}
            port={port}
            idx={idx}
            smoothProgress={smoothProgress}
          />
        ))}

        {/* FASE 3: THE CURTAIN OUTRO (Z-50) */}
        <OutroSection smoothProgress={smoothProgress} />
      </div>
    </section>
  );
}

// =====================================================================
// FASE 1: INTRO HERO SECTION (THE INK SPILL)
// =====================================================================
const IntroHeroSection = ({ smoothProgress }: { smoothProgress: any }) => {
  const text = "OUR PROJECT".split("");

  // THE FIX: Teks kecil & progress bar ditahan lebih lama!
  // Baru mulai pudar di 10% scroll, dan bener-bener hilang di 18% scroll.
  const fadeOut = useTransform(smoothProgress, [0.1, 0.25], [1, 0]);

  return (
    <motion.div
      style={{ opacity: fadeOut }}
      className="absolute inset-0 z-10 flex flex-col items-center justify-center pointer-events-none"
    >
      {/* TEKS BESAR "OUR PROJECT" (Per Huruf) */}
      <div className="flex flex-wrap justify-center px-4 text-center">
        {text.map((char, idx) => (
          <AnimatedInkLetter
            key={idx}
            char={char}
            idx={idx}
            progress={smoothProgress}
          />
        ))}
      </div>

      {/* TEKS KECIL & GARIS PROGRESS */}
      <motion.div
        initial={{ opacity: 0 }}
        whileInView={{ opacity: 1 }}
        viewport={{ once: false }} // Ikut keriset!
        // THE FIX: Delay dimundurin ke 0.8 biar nunggu teks gedenya setengah beres netes dulu
        transition={{ delay: 0.8, duration: 1 }}
        className="mt-12 flex flex-col items-center gap-6"
      >
        <p className="font-display text-sm font-black uppercase tracking-[0.3em] text-text-primary/60">
          Scroll to explore
        </p>
        <div className="h-24 w-0.5 overflow-hidden bg-text-primary/20">
          <motion.div
            animate={{ y: ["-100%", "100%"] }}
            transition={{ repeat: Infinity, duration: 1.5, ease: "linear" }}
            className="h-full w-full bg-text-primary"
          />
        </div>
      </motion.div>
    </motion.div>
  );
};

// --- LOGIKA ANIMASI TINTA TUMPAH PER HURUF ---
const AnimatedInkLetter = ({
  char,
  idx,
  progress,
}: {
  char: string;
  idx: number;
  progress: any;
}) => {
  // 1. THE RANDOMIZER 🎲: Urutan acak pseudo-random untuk 11 karakter "OUR PROJECT"
  // Urutan: O(7), U(2), R(9), Space(0), P(4), R(8), O(1), J(10), E(5), C(3), T(6)
  const randomOrder = [7, 2, 9, 0, 4, 8, 1, 10, 5, 3, 6];
  const rank = randomOrder[idx] || 0;

  // THE FIX: THE CINEMATIC HOLD & WIPE 🛑
  // startWipe digeser ke 0.10 (User harus scroll agak jauh baru mulai kehapus)
  // rank * 0.008 (Penyebaran hapus antar huruf dibikin lebih lebar)
  const startWipe = 0.1 + rank * 0.008;
  // THE FIX: Jarak hapusnya dibikin 0.05 (5x lipat lebih lama dari sebelumnya!)
  // User bisa bener-bener nikmatin proses tintanya ketarik ke atas.
  const endWipe = startWipe + 0.05;

  const reverseSpill = useTransform(
    progress,
    [startWipe, endWipe],
    ["inset(0% 0 0% 0)", "inset(0% 0 100% 0)"],
  );

  return (
    <motion.span style={{ clipPath: reverseSpill, display: "inline-block" }}>
      <motion.span
        initial={{ clipPath: "inset(0% 0 100% 0)" }}
        whileInView={{ clipPath: "inset(0% 0 0% 0)" }}
        viewport={{ once: false }} // THE RESET FIX 🛠️: Berubah jadi false biar keriset tiap masuk layar!
        // Delay dikalikan 0.12 (turunnya gantian lebih kerasa)
        // Duration dibikin 1.2 detik (turunnya pelan, elegan, dan berat)
        transition={{ delay: rank * 0.12, duration: 1.2, ease: "easeOut" }}
        className="font-display text-[14vw] desktop:text-[14vw] font-black uppercase tracking-tighter text-text-primary leading-none"
        style={{ display: "inline-block" }}
      >
        {char === " " ? "\u00A0" : char}
      </motion.span>
    </motion.span>
  );
};

// =====================================================================
// FASE 2: THE DIAGONAL DECK CARDS
// =====================================================================
const DiagonalDeckCard = ({
  port,
  idx,
  smoothProgress,
}: {
  port: any;
  idx: number;
  smoothProgress: any;
}) => {
  // TIMING MAPPING (Total Scroll buat Kartu: 0.15 sampai 0.85)
  // Tiap kartu dapet jatah waktu 0.15 untuk jalan dari ujung ke ujung
  const enterStart = 0.15 + idx * 0.15; // Masuk layar
  const centerPoint = 0.3 + idx * 0.15; // Di tengah layar
  const exitPoint = 0.45 + idx * 0.15; // Keluar layar

  const isLastCard = idx === 3;

  // 1. Translasi Diagonal (Infinite Train)
  const x = useTransform(
    smoothProgress,
    [enterStart, centerPoint, exitPoint],
    ["120vw", "0vw", isLastCard ? "0vw" : "-120vw"], // Kunci di tengah kalau ini kartu terakhir!
  );
  const y = useTransform(
    smoothProgress,
    [enterStart, centerPoint, exitPoint],
    ["120vh", "0vh", isLastCard ? "0vh" : "-120vh"],
  );

  // 2. Rotasi Lemparan
  const rotate = useTransform(
    smoothProgress,
    [enterStart, centerPoint, exitPoint],
    [0, 0, isLastCard ? 0 : -0],
  );

  // 3. Efek Mundur (Scale Down) saat kartu ditimpa kartu berikutnya
  const scale = useTransform(
    smoothProgress,
    [centerPoint, exitPoint],
    [1, isLastCard ? 1 : 0.9],
  );

  // Styling
  const isMint = idx % 2 === 0;
  const bgColor = isMint ? "bg-[#86EFAC]" : "bg-[#D8B4FE]";

  return (
    <motion.div
      style={{ x, y, rotate, scale, zIndex: 20 + idx }} // Z-index nambah biar yg masuk selalu di atas
      className={`absolute flex w-[80vw] max-w-175 flex-col rounded-2xl desktop:rounded-[2.5rem] border-[6px] border-[#000000] shadow-[12px_12px_0_#000000] ${bgColor}`}
    >
      <div
        className="absolute inset-0 z-50 cursor-pointer desktop:hidden"
        onClick={() => {
          sessionStorage.setItem("pendingProjectId", port.id);
          window.location.href = "/work";
        }}
      />

      {/* Pattern Titik */}
      <div
        className="pointer-events-none absolute inset-0 z-0 opacity-20"
        style={{
          backgroundImage: "radial-gradient(#000000 3px, transparent 3px)",
          backgroundSize: "24px 24px",
        }}
      />

      {/* Konten Portofolio Asli */}
      <div className="relative z-10 flex h-full flex-col p-6 sm:p-8 desktop:p-16">
        <div className="relative w-full aspect-4/3 grow rounded-2xl desktop:rounded-4xl border-4 border-[#000000] bg-surface-dark">
          <Image
            src={port.imageUrl}
            alt={port.headline}
            fill
            className="object-cover rounded-2xl desktop:rounded-4xl"
          />
        </div>
        <div className="flex items-end justify-between shrink-0 pt-6 desktop:pt-10">
          <div className="flex flex-col pr-4">
            <p className="font-display text-[12px] tablet-potrait:text-sm font-black uppercase tracking-widest text-[#000000]/60">
              {port.projectType}
            </p>
            <h4 className="font-display text-2xl desktop:text-[40px] font-black uppercase text-[#000000] mt-2 leading-none">
              {port.client}
            </h4>
          </div>
          <div
            onClick={() => {
              sessionStorage.setItem("pendingProjectId", port.id);
              window.location.href = "/work";
            }}
            className="hidden sm:flex shrink-0 cursor-pointer items-center justify-center rounded-full border-4 border-text-primary bg-[#FDE047] px-10 desktop:px-7 py-5 tablet-potrait:py-3.5 tablet:py-3 font-display text-lg desktop:text-[20px] font-black text-text-primary shadow-[4px_4px_0_rgba(0,0,0,1)] transition-transform duration-300 hover:bg-surface-light hover:-translate-y-1 hover:shadow-[6px_6px_0_rgba(0,0,0,1)] active:translate-y-0"
          >
            VIEW
          </div>
        </div>
      </div>
    </motion.div>
  );
};

// =====================================================================
// FASE 3: THE OUTRO CURTAIN (SECTION NAIK DARI BAWAH)
// =====================================================================
const OutroSection = ({ smoothProgress }: { smoothProgress: any }) => {
  // Outro mulai naik saat scroll 0.85 sampai 0.95, menutupi seluruh layar
  const y = useTransform(smoothProgress, [0.85, 0.9], ["100vh", "0vh"]);
  const [count, setCount] = useState(0);
  const countRef = useRef(null);
  const isInView = useInView(countRef, { margin: "-10% 0px" });

  const TOTAL_PROJECTS = portfolioData.length;

  useEffect(() => {
    let controls: AnimationPlaybackControls | undefined;

    if (isInView) {
      // Jalankan animasi maju saat masuk layar
      controls = animate(0, TOTAL_PROJECTS, {
        duration: 2,
        ease: "easeOut",
        onUpdate: (latest) => setCount(Math.round(latest)),
      });
    } else {
      // 2. RESET: Balikin ke 0 saat kartu keluar dari layar
      setCount(0);
    }

    return () => controls?.stop(); // Stop animasi kalau komponen unmount
  }, [isInView]);

  return (
    <motion.div
      style={{ y, zIndex: 50 }}
      ref={countRef}
      className="absolute inset-0 flex h-screen w-full flex-col items-center justify-center bg-pop-pink p-8 text-center border-t-8 border-text-primary"
    >
      <div className="mb-8 rounded-full border-4 border-text-primary bg-surface-light px-6 py-2 font-display text-sm font-black uppercase tracking-widest text-text-primary shadow-[4px_4px_0_rgba(0,0,0,1)]">
        STABLE BUILD: v2.0
      </div>
      <h3 className="font-display text-5xl font-black uppercase leading-none tracking-tighter text-text-primary sm:text-7xl desktop:text-[8rem]">
        {count} Systems Deployed.
      </h3>
      <p className="mt-8 max-w-lg text-lg font-bold leading-relaxed text-text-primary/70 sm:text-xl">
        Click to decrypt our mission reports and see how we engineered solutions
        for complex business logic.
      </p>
      <button
        onClick={() => (window.location.href = "/work")}
        className="mt-12 rounded-xl border-4 border-text-primary bg-pop-yellow px-12 py-5 font-display text-2xl font-black uppercase tracking-widest text-text-primary shadow-[8px_8px_0_rgba(0,0,0,1)] transition-all hover:-translate-y-1 hover:shadow-[12px_12px_0_rgba(0,0,0,1)] active:translate-y-0"
      >
        ACCESS DATA
      </button>
    </motion.div>
  );
};

// =====================================================================
// BACKGROUND PARALLAX DOODLES
// =====================================================================
const ParallaxDoodles = ({ smoothProgress }: { smoothProgress: any }) => {
  const [isMounted, setIsMounted] = useState(false);

  // Mencegah hydration error
  useEffect(() => {
    setIsMounted(true);
  }, []);

  if (!isMounted) return null;

  return (
    <div className="absolute inset-0 pointer-events-none"
    style={{
        /* JURUS CLIP-PATH INSET:
          Sintaks: inset(top right bottom left)
          - Top: -100vh (Artinya: Kasih ruang bebas 100% tinggi layar ke atas)
          - Right: 0 (Potong pas di pinggir kanan)
          - Bottom: 0 (Potong pas di pinggir bawah)
          - Left: 0 (Potong pas di pinggir kiri)
        */
        clipPath: 'inset(-100vh 0px 0px 0px)'
      }}
      >
      {doodleItem.map((src, index) => (
        <DoodleItem 
          key={`${src}-${index}`} 
          src={src} 
          smoothProgress={smoothProgress} 
        />
      ))}
    </div>
  );
};

const DoodleItem = ({ src, smoothProgress }: { src: string, smoothProgress: any }) => {
  const config = useMemo(() => {
    const goDown = Math.random() > 0.5;
    const distance = Math.floor(Math.random() * 500) + 500;
    const yRange = goDown ? [-distance, distance] : [distance, -distance];

    return {
      initialTop: Math.floor(Math.random() * 60) + 20,
      initialX: Math.floor(Math.random() * 80) + 10,
      yRange,
      rotateRange: [Math.random() * 360, Math.random() * 720],
      size: Math.floor(Math.random() * 30) + 90,
      
      // CONFIG BARU: Untuk Floating (Idle)
      floatDuration: Math.random() * 2 + 3, // Antara 3 - 5 detik
      floatDistance: Math.random() * 15 + 10, // Gerak naik turun 10-25px
      floatDelay: Math.random() * 2, // Biar nggak barengan geraknya
    };
  }, []);

  const y = useTransform(smoothProgress, [0, 1], config.yRange);
  const rotate = useTransform(smoothProgress, [0, 1], config.rotateRange);

  return (
    <motion.div
      style={{ 
        y, 
        rotate,
        left: `${config.initialX}%`,
        top: `${config.initialTop}%`,
      }}
      className="absolute z-0 pointer-events-none"
    >
      {/* DIV DALAM: Khusus untuk animasi Floating Idle */}
      <motion.div
        animate={{
          y: [0, -config.floatDistance, 0], // Naik turun
          rotate: [-2, 2, -2], // Sedikit goyang miring biar organik
        }}
        transition={{
          duration: config.floatDuration,
          repeat: Infinity,
          ease: "easeInOut",
          delay: config.floatDelay,
        }}
        style={{ width: `${config.size}px`, height: `${config.size}px` }} 
        className="relative"
      >
        <Image 
          src={src} 
          fill 
          alt="Doodle" 
          className="object-contain" 
        />
      </motion.div>
    </motion.div>
  );
};

"use client";

import { useEffect, useRef } from "react";
import gsap from "gsap";
import ScrollTrigger from "gsap/dist/ScrollTrigger";
import { testimonialsData } from "@/data/testimonials";

gsap.registerPlugin(ScrollTrigger);

const pastelColors = ["bg-pop-pink", "bg-pop-blue", "bg-pop-yellow", "bg-pop-green"];
const coloredTestimonials = testimonialsData.map((t, i) => ({
  ...t,
  color: pastelColors[i % pastelColors.length],
}));

// THE CLONES: Digandakan 3x lipat (Left Clones, Originals, Right Clones)
const marqueeCards = [...coloredTestimonials, ...coloredTestimonials, ...coloredTestimonials];

export default function Testimonials() {
  const containerRef = useRef<HTMLDivElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const cardsRef = useRef<(HTMLDivElement | null)[]>([]);

  useEffect(() => {
    if (!trackRef.current || !cardsRef.current.length) return;

    const originalCount = coloredTestimonials.length;
    // Tentukan indeks tengah (karena 5 kartu, tengahnya ada di indeks 2)
    const centerIndex = Math.floor(originalCount / 2); 
    
    // Pecah array jadi 3 pasukan
    const leftClones = cardsRef.current.slice(0, originalCount);
    const originalCards = cardsRef.current.slice(originalCount, originalCount * 2);
    const rightClones = cardsRef.current.slice(originalCount * 2);

    // BULLETPROOF MATH: Ambil jarak pasti antar kartu (Lebar + Gap)
    const card0 = originalCards[0];
    const card1 = originalCards[1];
    if (!card0 || !card1) return;
    
    const stepDistance = card1.offsetLeft - card0.offsetLeft; 
    const loopDistance = stepDistance * originalCount;

    // --- SETUP AWAL KOREOGRAFI ---
    // Posisi X awal lintasan agar kartu TENGAH dari pasukan 'Original' persis di tengah layar
    const startX = -(originalCount + centerIndex) * stepDistance;

    // 1. Sembunyikan pasukan kiri dan kanan
    gsap.set([leftClones, rightClones], { opacity: 0 });

    // 2. Geser rel ke titik startX 
    gsap.set(trackRef.current, { x: startX });

    // 3. Tumpuk pasukan 'Original' tepat di kartu tengahnya
    gsap.set(originalCards, {
      y: 400, // Mulai dari bawah layar
      opacity: 0,
      // RUMUS DEWA: Menumpuk kartu ke titik tengah. 
      // Yang kiri ketarik ke kanan, yang kanan ketarik ke kiri.
      x: (i) => (centerIndex - i) * stepDistance, 
      // Rotasi berantakan: Kartu tengah lurus, pinggiran miring
      rotation: (i) => (i - centerIndex) * 5, 
    });

    // --- MASTER TIMELINE ---
    const tl = gsap.timeline({
      scrollTrigger: {
        trigger: containerRef.current,
        start: "top 60%", 
        toggleActions: "play none none none",
      },
    });

    // 1. THE RISE: Tumpukan kartu naik dari bawah ke poros tengah layar
    tl.to(originalCards, {
      y: 0,
      opacity: 1,
      duration: 0.8,
      ease: "back.out(0.8)",
    });

    // 2. THE SYMMETRICAL DEAL: Kartu mekar ke kiri dan kanan dari tengah
    tl.to(originalCards, {
      x: 0, // Masing-masing kembali ke titik DOM aslinya (Mekar)
      rotation: 0, // Semuanya lurus kembali
      duration: 1.5,
      // Fitur dewa GSAP: Stagger dari tengah, jadi kartu tengah nyebar duluan/barengan sama pinggir
      stagger: { amount: 0.4, from: "center" }, 
      ease: "power3.out",
    });

    // 3. HOLD: Kasih jeda 0.5 detik biar user bisa nikmatin animasinya sejenak
    tl.to({}, { duration: 0.5 });

    // 4. SEAMLESS INJECTION: Munculkan pasukan kloningan kiri dan kanan secara halus
    tl.to([leftClones, rightClones], { opacity: 1, duration: 0.5 });

    // 5. INFINITE MARQUEE: Bikin rel berjalan selamanya
    tl.add(() => {
      gsap.fromTo(trackRef.current,
        { x: startX }, 
        { 
          x: startX - loopDistance, // Bergeser ke kiri persis sejauh 1 set
          duration: 25, 
          repeat: -1, 
          ease: "none" 
        }
      );
    });

    return () => {
      tl.kill();
      ScrollTrigger.getAll().forEach((t) => t.kill());
    };
  }, []);

  return (
    <section 
      ref={containerRef} 
      className="relative flex min-h-screen w-full flex-col items-center justify-center overflow-hidden bg-surface-light py-24"
    >
      <div className="relative z-10 mb-16 inline-block rounded-full border-2 border-text-primary bg-surface-light px-6 py-2 text-sm font-bold uppercase tracking-widest text-text-primary shadow-playful">
        CLIENT INSIGHTS
      </div>

      {/* TRACK CONTAINER */}
      {/* Pl-[calc] ini menggeser titik 0-nya. Digabungkan dengan startX GSAP, 
          maka kartu TENGAH dari tumpukan kita akan nongol sempurna di poros tengah monitor!
      */}
      <div className="w-full overflow-visible pl-[calc(50vw-160px)] desktop:pl-[calc(50vw-200px)]">
        
        <div ref={trackRef} className="flex w-max gap-6 desktop:gap-8">
          {marqueeCards.map((card, index) => (
            <div
              key={`${card.id}-${index}`}
              ref={(el) => { cardsRef.current[index] = el; }}
              className={`flex h-72 w-[320px] shrink-0 flex-col justify-between rounded-3xl border-4 border-text-primary p-6 shadow-playful desktop:h-80 desktop:w-100 desktop:p-8 ${card.color}`}
            >
              <div className="flex flex-col gap-2 desktop:gap-4">
                <span className="font-display text-4xl font-black leading-none text-text-primary opacity-20 desktop:text-6xl">
                  "
                </span>
                <p className="font-display text-lg font-black leading-tight text-text-primary desktop:text-xl">
                  {card.quote}
                </p>
              </div>

              <div className="mt-auto flex w-full justify-end">
                <p className="rounded-full border-2 border-text-primary bg-surface-light px-3 py-1.5 font-display text-[10px] font-bold uppercase tracking-widest text-text-primary desktop:px-4 desktop:py-2 desktop:text-xs">
                  {card.author}
                </p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence, PanInfo } from "framer-motion";
import { testimonialsData } from "@/data/testimonials";

const pastelColors = [
  "bg-pop-pink",   
  "bg-pop-blue",   
  "bg-pop-yellow", 
  "bg-pop-green"   
];

// Kita ikat warnanya permanen ke data awal agar warnanya tidak berubah-ubah saat array digeser
const coloredTestimonials = testimonialsData.map((t, i) => ({
  ...t,
  color: pastelColors[i % pastelColors.length]
}));

export default function Testimonials() {
  const [cards, setCards] = useState(coloredTestimonials);
  const [isHovered, setIsHovered] = useState(false);

  // LOGIKA ANIMASI OTOMATIS (Infinite Loop)
  useEffect(() => {
    // Kalau kursor masuk (onHover) atau layar disentuh, matikan timer-nya!
    if (isHovered) return;

    const timer = setInterval(() => {
      setCards((prev) => {
        const newArr = [...prev];
        // Cabut kartu paling depan, taruh di paling belakang
        newArr.push(newArr.shift()!);
        return newArr;
      });
    }, 2500); // Ganti kartu tiap 2.5 detik

    return () => clearInterval(timer);
  }, [isHovered]);

  // LOGIKA SWIPE MANUAL (Mobile & Desktop Drag)
  const handleDragEnd = (e: any, info: PanInfo) => {
    const swipeThreshold = 50; // Jarak minimal drag untuk dihitung sebagai swipe

    if (info.offset.x < -swipeThreshold) {
      // Geser Kiri -> Lanjut ke kartu berikutnya
      setCards((prev) => {
        const newArr = [...prev];
        newArr.push(newArr.shift()!);
        return newArr;
      });
    } else if (info.offset.x > swipeThreshold) {
      // Geser Kanan -> Balikin kartu sebelumnya
      setCards((prev) => {
        const newArr = [...prev];
        newArr.unshift(newArr.pop()!);
        return newArr;
      });
    }
  };

  return (
    <section className="relative flex min-h-screen w-full flex-col items-center justify-center overflow-hidden bg-surface-dark px-6 py-24 desktop:px-24">
      
      {/* Background Teks */}
      {/* <div className="absolute inset-0 z-0 flex items-center justify-center opacity-5 pointer-events-none">
        <h2 className="font-display text-[15vw] font-black uppercase leading-none tracking-tighter text-surface-light">
          Impact
        </h2>
      </div> */}

      <motion.div
        initial={{ opacity: 0, y: 20 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true }}
        className="relative z-10 mb-16 inline-block rounded-full border-2 border-text-primary bg-surface-light px-4 py-1.5 text-sm font-bold uppercase tracking-widest text-text-primary shadow-playful"
      >
        Word on the street
      </motion.div>

      {/* STACKING CAROUSEL ARENA */}
      <div 
        className="relative flex h-100 w-full max-w-md items-center justify-center desktop:h-112.5 desktop:max-w-xl"
        // Event listener untuk Pause on Hover
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        // Untuk Mobile (Tap & Hold)
        onTouchStart={() => setIsHovered(true)}
        onTouchEnd={() => setIsHovered(false)}
      >
        <AnimatePresence mode="popLayout">
          {cards.map((card, index) => {
            // OPTIMASI: Cukup render 3 kartu teratas agar DOM tidak berat.
            // Saat kartu ke-4 maju ke posisi 3, Framer Motion akan memunculkannya perlahan.
            if (index > 2) return null;

            const isFront = index === 0;

            return (
              <motion.div
                key={card.id}
                layout // Ini fitur magis yang bikin kartu di belakang maju ke depan dengan mulus
                initial={{ opacity: 0, scale: 0.8, y: 50 }}
                animate={{
                  opacity: 1 - index * 0.2, // Kartu belakang makin transparan (1, 0.8, 0.6)
                  scale: 1 - index * 0.05, // Kartu belakang makin kecil (1, 0.95, 0.9)
                  y: -index * 30, // Kartu belakang ditumpuk agak ke atas (-0, -30px, -60px)
                  zIndex: 10 - index, // Kartu depan z-index paling tinggi
                }}
                exit={{
                  opacity: 0,
                  x: -250, // Slide out "Terbang" ke kiri
                  rotate: -20, // Efek jatuh saat dibuang
                  transition: { duration: 0.3, ease: "easeIn" }
                }}
                transition={{
                  type: "spring",
                  stiffness: 400,
                  damping: 30,
                  delay: 0.30,
                }}
                // Bikin cuma kartu terdepan yang bisa di-drag
                drag={isFront ? "x" : false}
                dragConstraints={{ left: 0, right: 0 }}
                dragElastic={0.8}
                onDragEnd={isFront ? handleDragEnd : undefined}
                className={`absolute flex h-75 w-[320px] flex-col justify-between rounded-3xl border-4 border-text-primary p-6 shadow-playful desktop:h-87.5 desktop:w-112.5 desktop:p-8 ${card.color} ${isFront ? 'cursor-grab active:cursor-grabbing' : 'pointer-events-none'}`}
              >
                {/* Konten Teks (pointer-events-none agar tidak ganggu drag) */}
                <div className="flex flex-col gap-2 pointer-events-none desktop:gap-4">
                  <span className="font-display text-4xl font-black text-text-primary opacity-20 desktop:text-6xl">
                    "
                  </span>
                  <p className="font-display text-lg font-black leading-tight text-text-primary desktop:text-2xl">
                    {card.quote}
                  </p>
                </div>

                <div className="mt-auto flex w-full justify-end pointer-events-none">
                  <p className="rounded-full border-2 border-text-primary bg-surface-light px-3 py-1.5 font-display text-[10px] font-bold uppercase tracking-widest text-text-primary desktop:px-4 desktop:py-2 desktop:text-xs">
                    {card.author}
                  </p>
                </div>
              </motion.div>
            );
          })}
        </AnimatePresence>
      </div>
      
      {/* Visual Hint untuk User */}
      <motion.p 
        initial={{ opacity: 0 }}
        animate={{ opacity: 0.5 }}
        transition={{ delay: 1 }}
        className="relative z-10 mt-8 font-display text-sm font-bold tracking-widest text-surface-light uppercase"
      >
        *Hover to pause &bull; Swipe to explore
      </motion.p>

    </section>
  );
}

"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Send, Mail, CheckCircle2, AlertCircle, Loader2 } from "lucide-react";

type FormStatus = "idle" | "submitting" | "success" | "error";

export default function Contact() {
  const [status, setStatus] = useState<FormStatus>("idle");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    
    // 1. Ubah ke state Submitting (Form melipat)
    setStatus("submitting");

    // 2. Simulasi API Call (Delay 2 detik)
    setTimeout(() => {
      // Ubah ke state Success (Pesawat terbang)
      setStatus("success");
      
      // Reset form setelah 5 detik biar user bisa kirim pesan lagi
      setTimeout(() => setStatus("idle"), 5000);
    }, 2000);
  };

  return (
    <section className="relative flex min-h-screen w-full flex-col items-center justify-center overflow-hidden bg-surface-dark px-6 py-24 desktop:px-24">
      
      {/* Visual Hint */}
      <div className="relative z-10 mb-12 inline-block rounded-full border-2 border-text-primary bg-surface-light px-6 py-2 text-sm font-bold uppercase tracking-widest text-text-primary shadow-playful">
        Drop A Line
      </div>

      <div className="relative flex w-full max-w-4xl flex-col items-center justify-center desktop:flex-row desktop:items-start desktop:gap-12">
        
        {/* --- KOTAK POS (LOTTIE PLACEHOLDER) --- */}
        <div className="relative mb-12 flex h-64 w-full items-center justify-center rounded-[3rem] border-4 border-text-primary bg-pop-blue shadow-playful desktop:mb-0 desktop:w-1/2">
