            <Mail className="h-24 w-24 opacity-50" />
            <p className="mt-4 font-display text-xl font-black uppercase">Postbox Asset</p>
            <p className="text-sm font-bold opacity-70">(Lottie Placeholder)</p>
          </div>

          {/* Animasi Pesawat Kertas Terbang (Placeholder) */}
          <AnimatePresence>
            {status === "success" && (
              <motion.div
                initial={{ x: -200, y: 100, scale: 0, rotate: -45 }}
                animate={{ x: 0, y: 0, scale: 1, rotate: 0 }}
                exit={{ opacity: 0 }}
                transition={{ type: "spring", stiffness: 100, damping: 12 }}
                className="absolute z-30"
              >
                {/* Nanti ganti ini dengan Lottie Pesawat lu */}
                <div className="flex items-center justify-center rounded-full border-4 border-text-primary bg-surface-light p-4 shadow-playful">
                  <Send className="h-12 w-12 text-pop-pink" />
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* --- FORM SECTION --- */}
        <div className="relative w-full desktop:w-1/2">
          <AnimatePresence mode="wait">
            
            {/* STATE 1 & 2: IDLE ATAU SUBMITTING */}
            {(status === "idle" || status === "submitting" || status === "error") && (
              <motion.form
                key="contact-form"
                onSubmit={handleSubmit}
                // Animasi "Fold & Hold": Mengecil saat submitting, Goyang saat error
                animate={{
                  scale: status === "submitting" ? 0.9 : 1,
                  opacity: status === "submitting" ? 0.7 : 1,
                  x: status === "error" ? [-10, 10, -10, 10, 0] : 0,
                }}
                exit={{ opacity: 0, scale: 0.5, y: -50 }}
                transition={{ duration: 0.3 }}
                className="flex flex-col gap-6 rounded-[2.5rem] border-4 border-text-primary bg-surface-light p-8 shadow-playful desktop:p-10"
              >
                <div className="flex flex-col gap-2">
                  <label className="font-display font-black uppercase tracking-widest text-text-primary">Name</label>
                  <input 
                    type="text" 
                    required
                    disabled={status === "submitting"}
                    className="rounded-xl border-4 border-text-primary bg-surface-dark/5 px-4 py-3 font-bold text-text-primary outline-none transition-colors focus:border-pop-pink focus:bg-surface-light disabled:opacity-50"
                  />
                </div>

                <div className="flex flex-col gap-2">
                  <label className="font-display font-black uppercase tracking-widest text-text-primary">Message</label>
                  <textarea 
                    rows={4}
                    required
                    disabled={status === "submitting"}
                    className="resize-none rounded-xl border-4 border-text-primary bg-surface-dark/5 px-4 py-3 font-bold text-text-primary outline-none transition-colors focus:border-pop-yellow focus:bg-surface-light disabled:opacity-50"
                  />
                </div>

                {/* Tombol Dinamis */}
                <button
                  type="submit"
                  disabled={status === "submitting"}
                  className="group relative mt-4 overflow-hidden rounded-full border-4 border-text-primary bg-pop-yellow px-8 py-4 font-display text-xl font-black uppercase tracking-widest text-text-primary shadow-playful transition-all hover:bg-pop-pink hover:text-surface-light disabled:cursor-not-allowed disabled:bg-surface-dark/20 disabled:hover:text-text-primary"
                >
                  <span className="relative z-10 flex items-center justify-center gap-2">
                    {status === "idle" && "Send It"}
                    {status === "submitting" && (
                      <>
                        <Loader2 className="h-6 w-6 animate-spin" />
                        Folding...
                      </>
                    )}
                    {status === "error" && (
                      <>
                        <AlertCircle className="h-6 w-6" />
                        Try Again
                      </>
                    )}
                  </span>
                </button>
              </motion.form>
            )}

            {/* STATE 3: SUCCESS */}
            {status === "success" && (
              <motion.div
                key="success-msg"
                initial={{ opacity: 0, scale: 0.5, y: 50 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                className="flex h-full min-h-100 flex-col items-center justify-center rounded-[2.5rem] border-4 border-text-primary bg-pop-green p-8 text-center shadow-playful"
              >
                <CheckCircle2 className="mb-6 h-20 w-20 text-text-primary" />
                <h3 className="font-display text-4xl font-black uppercase leading-tight text-text-primary">
                  Message<br/>Delivered!
                </h3>
                <p className="mt-4 font-bold text-text-primary opacity-80">
                  I'll get back to you faster than this paper plane.
                </p>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

      </div>
    </section>
  );
}

"use client";

import { useState } from "react";
import { motion, AnimatePresence, Variants } from "framer-motion";
import {
  Copy,
  Calendar,
  Rocket,
  CheckCircle2,
  ArrowRight,
  ArrowLeft,
  Send,
} from "lucide-react";
import { GeneralData } from "@/data/general";
import { usePageTransition } from "@/hooks/UsePageTransition";
import { sendLaunchpadEmail } from "@/app/actions/ContactEmail";

// --- STATE MANAGEMENT ---
type FormData = {
  name: string;
  company: string;
  email: string;
  service: string;
  budget: string;
  currency: "IDR" | "USD";
  details: string;
};

const SERVICES = [
  "Web Platform",
  "Mobile App",
  "AI Integration",
  "IT Consulting",
];
const BUDGETS = {
  IDR: ["< Rp 50 Juta", "Rp 50Jt - 150Jt", "Rp 150Jt+"],
  USD: ["< $5k", "$5k - $15k", "$15k+"],
};

export default function ContactLaunchpad() {
  const [step, setStep] = useState(1);
  const [direction, setDirection] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [copied, setCopied] = useState(false);
  const [currency, setCurrency] = useState<"IDR" | "USD">("IDR");

  const isTransitionReady = usePageTransition();

  const [formData, setFormData] = useState<FormData>({
    name: "",
    company: "",
    email: "",
    service: "",
    budget: "",
    currency: "IDR",
    details: "",
  });

  const updateForm = (field: keyof FormData, value: string) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  const handleNext = () => {
    if (step < 4) {
      setDirection(1);
      setStep((s) => s + 1);
    }
  };

  const handlePrev = () => {
    if (step > 1) {
      setDirection(-1);
      setStep((s) => s - 1);
    }
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);

    // Panggil server action ke Resend
    const result = await sendLaunchpadEmail(formData);

    if (result.success) {
      setIsSubmitting(false);
      setIsSuccess(true); // Layar bakal ganti ke animasi Success buatan lu

      // Opsional: Balikin form ke awal kalau lu mau user bisa ngirim ulang setelah beberapa detik
      setTimeout(() => {
        setIsSuccess(false);
        setStep(1);
        setFormData({ ...formData, name: "", company: "", email: "", service: "", budget: "", details: "" });
      }, 5000);
    } else {
      setIsSubmitting(false);
      // Tampilkan error kalau koneksi/API gagal (pakai alert bawaan dulu gpp, atau modal kalau lu udah siapin)
      alert(
        "Mission Control Error: Failed to transmit data. Please try again.",
      );
    }
  };

  const handleCopyEmail = () => {
    navigator.clipboard.writeText(GeneralData[0].email);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  // --- ANIMATION VARIANTS (Slide & Pop) ---
  const slideVariants: Variants = {
    enter: (dir: number) => ({
      x: dir > 0 ? 100 : -100,
      opacity: 0,
      scale: 0.95,
    }),
    center: {
      x: 0,
      opacity: 1,
      scale: 1,
      transition: { type: "spring", stiffness: 300, damping: 25 },
    },
    exit: (dir: number) => ({
      x: dir < 0 ? 100 : -100,
      opacity: 0,
      scale: 0.95,
      transition: { type: "spring", stiffness: 300, damping: 25 },
    }),
  };

  const canGoNext = () => {
    if (step === 1)
      return formData.name.length > 0 && formData.email.includes("@");
    if (step === 2) return formData.service !== "";
    if (step === 3) return formData.budget !== "";
    return true;
  };

  return (
    <section className="relative flex min-h-screen w-full flex-col overflow-x-clip bg-surface-light desktop:flex-row">
      {/* =========================================
          SISI KIRI: THE SOCIAL & TRUST AREA (40%)
      ========================================= */}
      <motion.div
        initial={{ opacity: 0, x: -30 }}
        animate={
          isTransitionReady ? { opacity: 1, x: 0 } : { opacity: 0, x: -30 }
        }
        transition={{ duration: 0.8, ease: "easeOut" }}
        className="relative flex w-full flex-col justify-between border-b-2 border-text-primary bg-pop-yellow px-6 py-16 sm:px-12 desktop:sticky desktop:top-0 desktop:h-screen desktop:w-2/5 desktop:border-b-0 desktop:border-r-2 desktop:py-24"
      >
        <div className="mb-12 flex items-center gap-3">
          <div className="relative flex h-4 w-4 items-center justify-center">
            <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-pop-green opacity-75"></span>
            <span className="relative inline-flex h-3 w-3 rounded-full border-2 border-text-primary bg-pop-green"></span>
          </div>
          <span className="font-display text-sm font-black uppercase tracking-widest text-text-primary">
            Currently syncing new ideas
          </span>
        </div>

        <div className="mb-16">
          <h1 className="font-display text-5xl font-black uppercase leading-none tracking-tighter text-text-primary sm:text-6xl desktop:text-7xl">
            Let's turn that 'What If' into{" "}
            <span className="text-surface-light drop-shadow-[4px_4px_0_rgba(0,0,0,1)]">
              'Hell Yeah!'
            </span>
          </h1>
          <p className="mt-6 text-xl font-bold text-text-primary/80">
            Tell us about your mission. We don't bite, we byte (code).
          </p>
        </div>

        <div className="flex flex-col gap-4">
          <div className="flex items-center justify-between rounded-3xl border-2 border-text-primary bg-surface-light p-4 shadow-[4px_4px_0_rgba(0,0,0,1)]">
            <div className="flex flex-col">
              <span className="text-xs font-black uppercase tracking-widest text-text-primary/50">
                Drop an email
              </span>
              <span className="font-display text-lg font-black sm:text-xl">
                {GeneralData[0].email}
              </span>
            </div>
            <button
              onClick={handleCopyEmail}
              className="flex h-12 w-12 items-center justify-center rounded-xl border-2 border-text-primary bg-pop-pink shadow-[2px_2px_0_rgba(0,0,0,1)] transition-transform hover:-translate-y-1 active:translate-y-0"
            >
              {copied ? (
                <CheckCircle2 className="h-5 w-5" />
              ) : (
                <Copy className="h-5 w-5" />
              )}
            </button>
          </div>

          <a
            href={GeneralData[0].bookMeetingUrl}
            target="_blank"
            className="group flex flex-col justify-between rounded-3xl border-2 border-text-primary bg-pop-blue p-6 shadow-[4px_4px_0_rgba(0,0,0,1)] transition-transform hover:-translate-y-1"
          >
            <div className="mb-4 flex items-center gap-3">
              <div className="rounded-full border-2 border-text-primary bg-surface-light p-2">
                <Calendar className="h-5 w-5" />
              </div>
              <span className="font-display text-xl font-black uppercase">
                Book a Call
              </span>
            </div>
            <p className="font-bold text-text-primary/80">
              Prefer a human face? Grab a 15-min coffee chat.
            </p>
          </a>
        </div>
      </motion.div>

      {/* =========================================
          SISI KANAN: THE INQUIRY CONSOLE (60%)
      ========================================= */}
      <div className="relative flex w-full flex-col justify-center px-4 py-16 sm:px-12 desktop:w-3/5 desktop:px-24">
        {isSuccess ? (
          <motion.div
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            className="flex flex-col items-center text-center"
          >
            <div className="relative mb-8 flex h-32 w-32 items-center justify-center rounded-full border-2 border-text-primary bg-pop-green shadow-[6px_6px_0_rgba(0,0,0,1)]">
              <CheckCircle2 className="h-16 w-16 text-text-primary" />
              <motion.div
                animate={{ y: [-10, -30], x: [-10, -20], opacity: [1, 0] }}
                transition={{ repeat: Infinity, duration: 1 }}
                className="absolute h-3 w-3 rounded-full bg-pop-pink"
              />
              <motion.div
                animate={{ y: [-10, -40], x: [10, 30], opacity: [1, 0] }}
                transition={{ repeat: Infinity, duration: 1.2, delay: 0.2 }}
                className="absolute h-4 w-4 rounded-full bg-pop-yellow"
              />
              <motion.div
                animate={{ y: [10, 30], x: [-10, -40], opacity: [1, 0] }}
