                        <InlineFloatingInput
                          placeholder="COMPANY"
                          value={formData.company}
                          onChange={(e: any) =>
                            updateForm("company", e.target.value)
                          }
                          className="w-56 sm:w-80"
                          colorClass="bg-pop-blue"
                          textClass="text-pop-blue"
                        />
                        . You can reach me at
                        <InlineFloatingInput
                          type="email"
                          placeholder="EMAIL ADDRESS"
                          value={formData.email}
                          onChange={(e: any) =>
                            updateForm("email", e.target.value)
                          }
                          className="w-64 sm:w-96"
                          colorClass="bg-pop-green"
                          textClass="text-pop-green"
                        />
                        .
                      </h2>
                    </motion.div>
                  )}

                  {/* PHASE 2 */}
                  {step === 2 && (
                    <motion.div
                      key="step2"
                      custom={direction}
                      variants={slideVariants}
                      initial="enter"
                      animate="center"
                      exit="exit"
                      className="flex flex-col gap-6"
                    >
                      <h2 className="font-display text-3xl font-black uppercase leading-tight sm:text-4xl">
                        I have an exciting project! I need help with...
                      </h2>
                      <div className="mt-4 flex flex-wrap gap-4">
                        {SERVICES.map((srv) => (
                          <PillButton
                            key={srv}
                            label={srv}
                            isActive={formData.service === srv}
                            onClick={() => updateForm("service", srv)}
                          />
                        ))}
                      </div>
                    </motion.div>
                  )}

                  {/* PHASE 3 */}
                  {step === 3 && (
                    <motion.div
                      key="step3"
                      custom={direction}
                      variants={slideVariants}
                      initial="enter"
                      animate="center"
                      exit="exit"
                      className="flex flex-col gap-6"
                    >
                      <h2 className="font-display text-3xl font-black uppercase leading-tight sm:text-4xl">
                        My target launch is around
                      </h2>
                      <SquishyInput
                        placeholder="e.g. Next Month, Q3 2026..."
                        value={formData.details}
                        onChange={(e: any) =>
                          updateForm("details", e.target.value)
                        }
                      />

                      <div className="mt-8 flex flex-col items-start gap-4 sm:flex-row sm:items-center sm:justify-between">
                        <h2 className="font-display text-3xl font-black uppercase leading-tight sm:text-4xl">
                          and I'm allocating a budget of
                        </h2>

                        {/* --- THE CURRENCY TOGGLE --- */}
                        <div className="relative flex rounded-full border-2 border-text-primary bg-surface-dark/5 p-1 shadow-[2px_2px_0_rgba(0,0,0,1)]">
                          <button
                            onClick={() => {
                              setCurrency("IDR");
                              updateForm("budget", "");
                              updateForm("currency", "IDR");
                            }}
                            className={`relative z-10 px-4 py-2 font-display text-sm font-black uppercase tracking-widest transition-colors ${currency === "IDR" ? "text-text-primary" : "text-text-primary/50 hover:text-text-primary"}`}
                          >
                            IDR
                          </button>
                          <button
                            onClick={() => {
                              setCurrency("USD");
                              updateForm("budget", "");
                              updateForm("currency", "USD");
                            }}
                            className={`relative z-10 px-4 py-2 font-display text-sm font-black uppercase tracking-widest transition-colors ${currency === "USD" ? "text-text-primary" : "text-text-primary/50 hover:text-text-primary"}`}
                          >
                            USD
                          </button>

                          {/* Animated Slider Background */}
                          <motion.div
                            className="absolute bottom-1 top-1 z-0 rounded-full border-2 border-text-primary bg-pop-yellow shadow-playful"
                            initial={false}
                            animate={{
                              left: currency === "IDR" ? "4px" : "50%",
                              width: "calc(50% - 4px)",
                            }}
                            transition={{
                              type: "spring",
                              stiffness: 400,
                              damping: 30,
                            }}
                          />
                        </div>
                      </div>

                      {/* BUDGET PILLS (Ngerender dinamis berdasarkan kurs yang dipilih) */}
                      <div className="mt-2 flex flex-wrap gap-4">
                        {BUDGETS[currency].map((bg) => (
                          <PillButton
                            key={bg}
                            label={bg}
                            isActive={formData.budget === bg}
                            onClick={() => updateForm("budget", bg)}
                          />
                        ))}
                      </div>
                    </motion.div>
                  )}

                  {/* PHASE 4 */}
                  {step === 4 && (
                    <motion.div
                      key="step4"
                      custom={direction}
                      variants={slideVariants}
                      initial="enter"
                      animate="center"
                      exit="exit"
                      className="flex flex-col gap-6"
                    >
                      <h2 className="font-display text-3xl font-black uppercase leading-tight sm:text-4xl">
                        Here's a little secret about the project:
                      </h2>
                      <motion.div
                        whileFocus="focused"
                        initial="idle"
                        className="relative mt-2 w-full"
                      >
                        <textarea
                          rows={5}
                          placeholder="Tell us more about the goals, the vibe, or any crazy ideas..."
                          value={formData.details}
                          onChange={(e) =>
                            updateForm("details", e.target.value)
                          }
                          className="peer relative z-10 w-full resize-none rounded-2xl border-2 border-text-primary bg-surface-dark/5 p-6 text-xl font-bold text-text-primary outline-none transition-all focus:bg-surface-light"
                        />
                        <motion.div
                          variants={{
                            idle: { scaleX: 0 },
                            focused: { scaleX: 1 },
                          }}
                          transition={{ duration: 0.3 }}
                          className="absolute bottom-0 left-0 right-0 z-20 h-1 origin-center rounded-b-2xl bg-pop-pink"
                        />
                      </motion.div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>

              <div className="mt-12 flex items-center justify-between border-t-2 border-text-primary/10 pt-8">
                {step > 1 ? (
                  <button
                    onClick={handlePrev}
                    className="flex items-center gap-2 font-display text-sm font-black uppercase tracking-widest text-text-primary transition-transform hover:-translate-x-2"
                  >
                    <ArrowLeft className="h-5 w-5" /> Back
                  </button>
                ) : (
                  <div />
                )}

                {step < 4 ? (
                  <button
                    onClick={handleNext}
                    disabled={!canGoNext()}
                    className="flex items-center gap-2 rounded-full border-2 border-text-primary bg-pop-yellow px-8 py-4 font-display text-lg font-black uppercase tracking-widest shadow-[4px_4px_0_rgba(0,0,0,1)] transition-all hover:-translate-y-1 hover:bg-pop-pink hover:shadow-[6px_6px_0_rgba(0,0,0,1)] active:translate-y-0 disabled:pointer-events-none disabled:opacity-50"
                  >
                    Continue <ArrowRight className="h-5 w-5" />
                  </button>
                ) : (
                  <button
                    onClick={handleSubmit}
                    disabled={isSubmitting || formData.details === ""}
                    className="group relative overflow-hidden flex items-center justify-center gap-2 rounded-full border-2 border-text-primary bg-pop-green px-10 py-4 font-display text-lg font-black uppercase tracking-widest shadow-[4px_4px_0_rgba(0,0,0,1)] transition-all hover:-translate-y-1 hover:shadow-[6px_6px_0_rgba(0,0,0,1)] active:translate-y-0 disabled:pointer-events-none disabled:opacity-80"
                  >
                    {isSubmitting && (
                      <motion.div
                        initial={{ x: "-100%" }}
                        animate={{ x: "0%" }}
                        transition={{ duration: 2, ease: "linear" }}
                        className="absolute inset-0 z-0 bg-pop-yellow"
                      />
                    )}
                    <span className="relative z-10 flex items-center gap-2">
                      {isSubmitting ? "Initiating..." : "Launch Project"}
                      {!isSubmitting && (
                        <Send className="h-5 w-5 transition-transform group-hover:translate-x-1 group-hover:-translate-y-1" />
                      )}
                    </span>
                  </button>
                )}
              </div>
            </motion.div>
          </div>
        )}
      </div>
    </section>
  );
}

// --- MICRO-COMPONENTS ---

// 1. KOMPONEN BARU: The Inline Floating Input (Mad Libs Seamless)
const InlineFloatingInput = ({
  placeholder,
  value,
  onChange,
  type = "text",
  className = "w-48",
  colorClass = "bg-pop-pink",
  textClass = "text-pop-pink",
}: any) => {
  const [isFocused, setIsFocused] = useState(false);
  const isFloating = isFocused || value.length > 0;

  return (
    <div className={`relative mx-3 inline-block align-baseline ${className}`}>
      {/* The Floating Placeholder */}
      <motion.span
        animate={{
          y: isFloating ? -40 : 0,
          scale: isFloating ? 0.45 : 1,
        }}
        transition={{ type: "spring", stiffness: 300, damping: 25 }}
        className={`absolute bottom-5 left-0 origin-bottom-left pointer-events-none font-display text-3xl font-black uppercase sm:text-4xl transition-colors duration-300 ${isFloating ? textClass : "text-text-primary/30"}`}
      >
        {placeholder}
      </motion.span>

      {/* The Clean Input */}
      <input
        type={type}
        // Jangan pakai attribute placeholder bawaan HTML biar nggak dobel
        placeholder=""
        value={value}
        onChange={onChange}
        onFocus={() => setIsFocused(true)}
        onBlur={() => setIsFocused(false)}
        className="relative z-10 w-full bg-transparent pb-1 font-display text-3xl font-black uppercase text-text-primary outline-none sm:text-4xl"
      />

      {/* Base Subtle Underline */}
      <div className="absolute bottom-4 left-0 right-0 h-0.75 rounded-full bg-text-primary/10" />

      {/* Animated Center-Out Underline */}
      <motion.div
        initial={false}
        animate={{ scaleX: isFocused ? 1 : 0 }}
        transition={{ duration: 0.3, ease: "easeInOut" }}
        className={`absolute bottom-4 left-0 right-0 z-20 h-1 origin-center rounded-full ${colorClass}`}
      />
    </div>
  );
};

// 2. The Boxy Squishy Input (Phase 3)
const SquishyInput = ({ placeholder, value, onChange, type = "text" }: any) => {
  return (
    <motion.div
      initial="idle"
      whileFocus="focused"
      whileHover="hover"
      className="relative w-full"
    >
      <motion.input
        type={type}
        placeholder={placeholder}
        value={value}
        onChange={onChange}
        variants={{
          idle: { scale: 1 },
          hover: { scale: 1.01 },
          focused: { scale: 1.02 },
        }}
        transition={{ type: "spring", stiffness: 400, damping: 25 }}
        className="peer relative z-10 w-full rounded-2xl border-2 border-text-primary bg-surface-dark/5 px-6 py-5 text-xl font-bold text-text-primary outline-none transition-colors placeholder:text-text-primary/40 focus:bg-surface-light"
      />
      <motion.div
        variants={{
          idle: { scaleX: 0 },
          hover: { scaleX: 0 },
          focused: { scaleX: 1 },
        }}
        transition={{ duration: 0.3 }}
        className="absolute bottom-0 left-0 right-0 z-20 h-1 origin-center rounded-b-2xl bg-pop-pink"
      />
    </motion.div>
  );
};

// 3. Pill Button
const PillButton = ({
  label,
  isActive,
  onClick,
}: {
  label: string;
  isActive: boolean;
  onClick: () => void;
}) => {
  return (
    <button
      onClick={onClick}
      className={`relative rounded-full border-2 border-text-primary px-6 py-3 font-display text-sm font-black uppercase tracking-widest transition-all ${
        isActive
          ? "bg-pop-blue text-text-primary shadow-[4px_4px_0_rgba(0,0,0,1)] -translate-y-1"
          : "bg-surface-light text-text-primary hover:bg-surface-dark/5 hover:-translate-y-1"
      }`}
    >
      {label}
    </button>
  );
};

"use client";

import { useState, useEffect, useRef } from "react";
import { motion, AnimatePresence, Variants, useScroll, useSpring, useTransform } from "framer-motion";
import {
  ArrowRight,
  ArrowLeft,
  ExternalLink,
  Calendar,
  Briefcase,
  User,
} from "lucide-react";
import { portfolioData } from "@/data/portfolio";
import { useRouter, usePathname } from "next/navigation";
import { Suspense } from "react";
import { usePageTransition } from "@/hooks/UsePageTransition";

const CATEGORIES = ["All", "Web App", "AI & System", "Backend", "E-Commerce"];

// --- VARIAN ANIMASI UNTUK DETAIL PORTOFOLIO ---
const staggerContainer: Variants = {
  hidden: { opacity: 0 },
  show: {
    opacity: 1,
    transition: {
      staggerChildren: 0.15,
      delayChildren: 0.4, 
    },
  },
  exit: {
    opacity: 0,
    transition: { staggerChildren: 0.05, staggerDirection: -1 },
  }
};

const slideUpItem: Variants = {
  hidden: { opacity: 0, y: 40, scale: 0.98 },
  show: { 
    opacity: 1, 
    y: 0, 
    scale: 1, 
    transition: { type: "spring", stiffness: 250, damping: 20 } 
  },
  exit: { opacity: 0, y: 20, transition: { duration: 0.2 } }
};

// --- KOMPONEN: OVERLAY DETAIL (FULL SCREEN) ---
const ProjectDetail = ({
  project,
  onClose,
}: {
  project: (typeof portfolioData)[0];
  onClose: () => void;
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  
  // STATE BARU: Melacak indeks gambar showcase yang sedang di-zoom
  const [zoomedImageIdx, setZoomedImageIdx] = useState<number | null>(null);

  const { scrollYProgress } = useScroll({
    container: containerRef,
    offset: ["start start", "end end"],
  });

  const smoothProgress = useSpring(scrollYProgress, {
    mass: 0.5,
    stiffness: 100,
    damping: 30,
    restDelta: 0.001
  });

  const progressWidth = useTransform(smoothProgress, [0, 1], ["0%", "100%"]);

  useEffect(() => {
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = "unset"; };
  }, []);

  useEffect(() => {
    // Penjaga ini cuma aktif pas gambar lagi di-zoom!
    if (zoomedImageIdx !== null) {
      
      // Fungsi eksekutor untuk mematikan scroll bawaan (Native Scroll Browser)
      const killNativeScroll = (e: Event) => {
        e.preventDefault();
      };

      // Pasang gembok di level paling akar (window)
      // Opsi { passive: false } ini WAJIB MANTLUL ada, kalau nggak browser bakal nge-block preventDefault() lu.
      window.addEventListener("touchmove", killNativeScroll, { passive: false });
      window.addEventListener("wheel", killNativeScroll, { passive: false });

      return () => {
        // Buka gembok saat gambar ditutup / di-discard (drag)
        window.removeEventListener("touchmove", killNativeScroll);
        window.removeEventListener("wheel", killNativeScroll);
      };
    }
  }, [zoomedImageIdx]);

  return (
    <>
      <motion.div
        ref={containerRef}
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className={`fixed inset-0 z-100 h-dvh w-full overflow-x-clip overscroll-none bg-surface-light custom-scrollbar ${
          zoomedImageIdx !== null ? "overflow-hidden" : "overflow-y-auto"
        }`}
      >
        {/* TOP COMMAND BAR & PROGRESS INDICATOR */}
        <motion.div 
          initial={{ y: -100 }}
          animate={{ y: 0 }}
          exit={{ y: -100 }}
          transition={{ type: "spring", stiffness: 300, damping: 25, delay: 0.2 }}
          className="sticky top-0 z-110 w-full border-b-4 border-text-primary bg-surface-light shadow-[0_4px_0_rgba(0,0,0,1)]"
        >
          <div className="flex w-full justify-between px-6 py-4 pointer-events-none sm:px-12 items-center">
            <div className="flex items-center gap-3">
               <div className="h-3 w-3 rounded-full bg-pop-pink animate-pulse" />
               <span className="font-mono text-sm font-bold uppercase tracking-widest text-text-primary hidden sm:block">
                 Previewing: {project.id}
               </span>
            </div>
            <button
              onClick={onClose}
              className="pointer-events-auto flex items-center gap-2 rounded-full border-4 border-text-primary bg-pop-yellow px-6 py-2 font-display text-sm font-black uppercase text-text-primary shadow-[4px_4px_0_rgba(0,0,0,1)] transition-all hover:-translate-y-1 hover:bg-pop-pink hover:shadow-[6px_6px_0_rgba(0,0,0,1)] active:translate-y-0"
            >
              <ArrowLeft className="h-5 w-5" /> Back to Archive
            </button>
